clean_ddl:
CREATE TABLE GASSTATIONS (
    GASSTATIONID INT,
    COUNTRY VARCHAR,
    PRIMARY KEY (GasStationID)
);

CREATE TABLE TRANSACTIONS_1K (
    TRANSACTIONID INT,
    GASSTATIONID INT,
    PRODUCTID INT,
    PRICE REAL,
    PRIMARY KEY (TransactionID)
);

counterexample:
INSERT INTO gasstations (GasStationID, Country) VALUES (1, 'USA');
