-- Note: To see the difference in behavior, consider creating the tables with a different case, such as 'Transactions_1k' instead of 'transactions_1k', and note quotations with '"Transactions_1k"' in other environments.

clean_ddl:
CREATE TABLE CUSTOMERS (
    CUSTOMERID INT,
    PRIMARY KEY (CustomerID)
);

CREATE TABLE PRODUCTS (
    PRODUCTID INT,
    PRIMARY KEY (ProductID)
);

CREATE TABLE TRANSACTIONS_1K (
    TRANSACTIONID INT,
    CUSTOMERID INT,
    PRODUCTID INT,
    AMOUNT INT,
    PRICE REAL,
    PRIMARY KEY (TransactionID)
);

CREATE TABLE YEARMONTH (
    CUSTOMERID INT,
    DATE VARCHAR,
    CONSUMPTION REAL,
    PRIMARY KEY (Date, CustomerID),
    FOREIGN KEY (CustomerID) REFERENCES customers(CustomerID)
);

counterexample:
INSERT INTO CUSTOMERS (CUSTOMERID) VALUES (1);
INSERT INTO PRODUCTS (PRODUCTID) VALUES (5);
INSERT INTO TRANSACTIONS_1K (TRANSACTIONID, CUSTOMERID, PRODUCTID, AMOUNT, PRICE) VALUES (1, 1, 5, 1, 30.00);
INSERT INTO YEARMONTH (CUSTOMERID, DATE, CONSUMPTION) VALUES (1, '20120801', 100.00);
